 "Dělicí křivka je rovinná (skica kolmá na tah) – stupňovitý úkos je zde totožný s úkosem kolem dělicí roviny.": "Die Trennlinie ist eben (Skizze senkrecht zur Entformungsrichtung) – die gestufte Schräge ist hier identisch mit der Schräge um die Trennebene.",
