 "Dělicí křivka leží mimo těleso.": "Die Trennlinie liegt außerhalb des Körpers.",
 "Dělicí křivka musí být jedna souvislá čára (skica „{0}“ má mezery nebo větve).": "Die Trennlinie muss eine zusammenhängende Linie sein (Skizze „{0}“ hat Lücken oder Verzweigungen).",
 "Dělicí křivka musí mít aspoň dva body.": "Die Trennlinie braucht mindestens zwei Punkte.",
 "Dělicí křivka se ve směru kolmém na tah vrací – každému místu smí odpovídat jediná výška (svislé skoky jsou dovoleny).": "Die Trennlinie läuft quer zur Entformungsrichtung zurück – jeder Stelle darf nur eine Höhe entsprechen (senkrechte Sprünge sind erlaubt).",
 "Dělicí plocha těleso nerozdělila – zkontrolujte polohu skici dělicí křivky.": "Die Trennfläche hat den Körper nicht geteilt – prüfen Sie die Lage der Trennlinien-Skizze.",
