 "díra: ": "Bohrung: ",
 "díra: „dno ploché“ / „hrot“ platí jen pro slepou díru s hloubkou: díra 10 hloubka 12 dno ploché": "Bohrung: „flacher Grund“ / „Spitze“ gelten nur für ein Sackloch mit Tiefe: bohrung 10 tiefe 12 flacher grund",
 "díra: „jádro“ a „vrták“ platí jen pro závitovou díru: díra závit M8 hloubka 20 jádro": "Bohrung: „Kern“ und „Bohrer“ gelten nur für eine Gewindebohrung: bohrung gewinde M8 tiefe 20 kern",
 "díra: „jádro“ a „vrták“ si odporují – zadejte jen jedno": "Bohrung: „Kern“ und „Bohrer“ widersprechen sich – nur eines angeben",
 "díra: dno je zadané dvakrát různě („{0}“) – použijte buď „dno ploché“, nebo „hrot 118“": "Bohrung: der Grund ist zweimal unterschiedlich angegeben („{0}“) – entweder „flacher Grund“ oder „Spitze 118“ verwenden",
 "díra: nerozumím slovu „{0}“ – volby dna a vrtáku: dno ploché | hrot 118 | dno kužel | jádro | vrták [6,7]; název pište za slovo „název“": "Bohrung: das Wort „{0}“ verstehe ich nicht – Grund- und Bohreroptionen: flacher Grund | Spitze 118 | Grund Kegel | Kern | Bohrer [6,7]; einen Namen hinter das Wort „name“ schreiben",
 "díra: průměr {0} a „jádro“ (D1 závitu {1} = {2}) si odporují – zadejte jen jedno": "Bohrung: Durchmesser {0} und „Kern“ (D1 des Gewindes {1} = {2}) widersprechen sich – nur eines angeben",
 "díra: průměr {0} a „vrták {1}“ si odporují – zadejte jen jedno": "Bohrung: Durchmesser {0} und „Bohrer {1}“ widersprechen sich – nur eines angeben",
 "díra: průměr {0} a „vrták“ (tabulkový {1} pro {2}) si odporují – zadejte jen jedno": "Bohrung: Durchmesser {0} und „Bohrer“ (Tabelle {1} für {2}) widersprechen sich – nur eines angeben",
 "díra: průměr vrtáku musí být kladný: vrták 6,7": "Bohrung: der Bohrerdurchmesser muss positiv sein: bohrer 6,7",
 "díra: úhel hrotu {0}° – zadejte 60 až 170° (vrták 118°, 120°, 90°…) nebo 180 = ploché dno": "Bohrung: Spitzenwinkel {0}° – 60 bis 170° angeben (Bohrer 118°, 120°, 90°…) oder 180 = flacher Grund",
 "díra: vrták Ø{0} musí být menší než závit {1} (Ø{2}) – průchozí díra pro šroub je díra bez závitu (např. díra 9 skrz)": "Bohrung: Bohrer Ø{0} muss kleiner als das Gewinde {1} (Ø{2}) sein – ein Durchgangsloch für eine Schraube ist eine Bohrung ohne Gewinde (z. B. bohrung 9 durch)",
