 "Housenka je prázdná – zkontrolujte délku úseku a rozteč.": "Die Naht ist leer – Abschnittslänge und Teilung prüfen.",
 "Housenka je rovnoramenný trojúhelník z × z v koutu (rovné hrany i oblouky); kolem = celá uzavřená smyčka koutu s vyplněnými rohy. Délka, průřez, hmotnost svarového kovu a přídavný materiál jsou ve stavu prvku a v Tabulce svarů.": "Die Naht ist ein gleichschenkliges Dreieck z × z in der Ecke (gerade Kanten und Bögen); ringsum = die ganze geschlossene Eckschleife mit gefüllten Ecken. Länge, Querschnitt, Schweißgutmasse und Zusatzwerkstoff stehen im Elementstatus und in der Schweißnahttabelle.",
 "Housenku lze vést po rovné hraně nebo oblouku (hrana {0}).": "Eine Naht kann einer geraden Kante oder einem Bogen folgen (Kante {0}).",
