 "Hrana {0} je zčásti vypuklá a zčásti vnitřní – eliptické zaoblení ji neumí; rozdělte ji nebo použijte konstantní zaoblení.": "Kante {0} ist teils konvex, teils konkav – die elliptische Verrundung kann sie nicht; teilen Sie sie oder verwenden Sie eine konstante Verrundung.",
 "Hrana {0} nesousedí právě se dvěma plochami – eliptické zaoblení na ní nelze vytvořit.": "Kante {0} grenzt nicht an genau zwei Flächen – darauf ist keine elliptische Verrundung möglich.",
 "Hrana {0} patří svaru – vyberte hranu spojovaného dílu.": "Kante {0} gehört zu einer Naht – eine Kante eines gefügten Teils wählen.",
 "Hrana {0} se po změně modelu nenašla podle otisku – použit původní index.": "Kante {0} wurde nach der Modelländerung nicht über ihren Fingerabdruck gefunden – der ursprüngliche Index wird verwendet.",
 "Hrana {0} se po změně modelu nenašla podle otisku a těleso ji už nemá (hran: {1}) – vyberte ji znovu.": "Kante {0} wurde nach der Modelländerung nicht über ihren Fingerabdruck gefunden und der Körper hat sie nicht mehr ({1} Kanten) – wählen Sie sie erneut aus.",
 "Hrana {0} v tělese neexistuje – vyberte hranu znovu.": "Kante {0} existiert im Körper nicht – wählen Sie die Kante erneut.",
