 "Hrana / válcová plocha": "Kante / Zylinderfläche",
 "Hrana čela na straně svaru (strana šipky), nebo vnitřní kout sloučeného T / rohového spoje.": "Kante der Stirnfläche auf der Nahtseite (Pfeilseite) oder die innere Ecke eines vereinigten T- / Eckstoßes.",
