 "hrana E{0} v tělese není – těleso má {1} hran (E1 až E{1})": "Kante E{0} ist nicht im Körper – der Körper hat {1} Kanten (E1 bis E{1})",
 "Hrana je rovnoběžná s plochou – průsečík neexistuje.": "Die Kante ist parallel zur Fläche – es gibt keinen Schnittpunkt.",
 "Hrana modelu": "Modellkante",
 "Hrana musí ležet mezi dvěma plochami tělesa.": "Die Kante muss zwischen zwei Flächen des Körpers liegen.",
 "Hrana musí ležet mezi plochou plechu a boční plochou (rovná hrana obrysu).": "Die Kante muss zwischen der Blechfläche und einer Seitenfläche liegen (gerade Konturkante).",
 "Hrana nebo kružnice, ke které se kóta váže, v pohledu není (model se změnil) – kreslí se podle uložených údajů. Zkontrolujte ji nebo ji vložte znovu.": "Die Kante oder der Kreis, auf die sich das Maß bezieht, ist in der Ansicht nicht mehr vorhanden (das Modell wurde geändert) – es wird nach den gespeicherten Daten gezeichnet. Prüfen Sie es oder fügen Sie es neu ein.",
 "Hrana není kruhová – střed kružnice nelze určit (použijte střed hrany).": "Die Kante ist nicht kreisförmig – der Kreismittelpunkt kann nicht bestimmt werden (verwenden Sie die Kantenmitte).",
 "Hrana není vnitřní (konkávní) a nedotýká se jiného dílu – housenka se dělá do koutu mezi dvěma plochami nebo dvěma díly.": "Die Kante ist nicht konkav und berührt kein anderes Teil – eine Naht liegt in einer Ecke zwischen zwei Flächen oder zwei Teilen.",
