 "Jádro se nenačetlo": "Der Kern wurde nicht geladen",
 "Jádro soubor přečetlo, ale nevzniklo žádné těleso ani plocha (prázdný soubor, jen křivky nebo body). Zkontrolujte export ve zdrojovém programu (STEP AP214, tělesa).": "Der Kern hat die Datei gelesen, aber es entstand kein Körper und keine Fläche (leere Datei, nur Kurven oder Punkte). Prüfen Sie den Export im Quellprogramm (STEP AP214, Volumenkörper).",
 "Jádro šíří zaoblení po tečně navazujících hranách (hrana → oblouk → hrana) i samo; volba rozšíří i výběr, se kterým pracuje tabulka a počet hran.": "Der Kern setzt die Verrundung entlang tangential anschließender Kanten (Kante → Bogen → Kante) von selbst fort; die Option erweitert auch die Auswahl, mit der Tabelle und Kantenzahl arbeiten.",
 "jádro v souboru nenašlo těleso": "der Kern hat in der Datei keinen Körper gefunden",
 "Jádru CAD došla paměť – model je pro prohlížeč příliš velký. Jádro bylo spuštěno znovu. Velkou sestavu STEP otevřete jako sestavu (díly se čtou zvlášť), zavřete ostatní záložky nebo skryjte část komponent.": "Dem CAD-Kern ist der Speicher ausgegangen – das Modell ist für den Browser zu groß. Der Kern wurde neu gestartet. Öffnen Sie eine große STEP-Baugruppe als Baugruppe (Teile werden einzeln gelesen), schließen Sie andere Registerkarten oder blenden Sie einen Teil der Komponenten aus.",
