 "Kategorie": "Kategorien",
 "Každá hrana může mít vlastní poloměr; liší-li se začátek a konec, mění se poloměr podél hrany lineárně. Řídicí body uprostřed hrany jádro neumožňuje; tečně navazující hrany tvoří jeden přechod se společným poloměrem.": "Jede Kante kann einen eigenen Radius haben; unterscheiden sich Anfang und Ende, ändert sich der Radius entlang der Kante linear. Steuerpunkte in Kantenmitte unterstützt der Kern nicht; tangential anschließende Kanten bilden einen Übergang mit gemeinsamem Radius.",
