 "Kusy se číslují v pořadí řad (zdola nahoru, zleva doprava), u kruhového od středu po prstencích.": "Instanzen werden reihenweise nummeriert (von unten nach oben, von links nach rechts), beim Kreismuster von der Mitte ringweise.",
 "Kusy se rozmístí po délce křivky od jejího začátku; u uzavřené křivky po celém obvodu. Referenční bod zdroje = střed jeho obalového kvádru: kopie se posunou o vzdálenost bodu křivky od jejího začátku a (u tečného natočení) otočí kolem tohoto středu.": "Die Instanzen werden entlang der Kurve ab ihrem Anfang verteilt; bei geschlossener Kurve über den gesamten Umfang. Referenzpunkt der Quelle = Mitte ihres Hüllquaders: Kopien werden um den Abstand des Kurvenpunkts vom Kurvenanfang verschoben und (bei tangentialer Ausrichtung) um diese Mitte gedreht.",
