 "Odkaz zkopírován – vložte ho do zprávy (Ctrl+V).": "Link kopiert – fügen Sie ihn in eine Nachricht ein (Strg+V).",
 "Odkaz zneplatněn – šifrovaný dokument byl ze serveru smazán.": "Link ungültig gemacht – das verschlüsselte Dokument wurde vom Server gelöscht.",
