 "Odkazovaná {0} už v modelu není – vyberte ji znovu.": "Die referenzierte {0} ist nicht mehr im Modell – wählen Sie sie erneut.",
 "odkazy místo čísel: osa rotace a kruhového pole hranou, osou válcové plochy, pomocnou osou nebo dvěma body; směr řady pole hranou / dvěma body; rovina zrcadlení plochou nebo pomocnou rovinou; sražení vzdálenost + úhel nebo dvě vzdálenosti od referenční plochy; hrany a plochy čísly (E, F jako popisky pro výběr) místo pravidla": "Referenzen statt Zahlen: Achse von Rotation und Kreismuster per Kante, Achse einer Zylinderfläche, Hilfsachse oder zwei Punkte; Richtung des linearen Musters per Kante / zwei Punkte; Spiegelebene per Fläche oder Hilfsebene; Fase Abstand + Winkel oder zwei Abstände von einer Bezugsfläche; Kanten und Flächen per Nummer (E, F wie die Auswahlbeschriftungen) statt einer Regel",
