 "Odstraní díry, čepy, kuželová zahloubení a válcová zaoblení (obnoví ostrou hranu). Vhodné pro úpravy importovaných modelů.": "Entfernt Bohrungen, Zapfen, Kegelsenkungen und zylindrische Verrundungen (stellt die scharfe Kante wieder her). Geeignet zur Bearbeitung importierter Modelle.",
