 "Odstup od okraje": "Randabstand",
 "Odvozeno z historie prvků – pomocný seznam, ne náhrada kontroly konstruktérem. Chybějící kótu přidáte nástrojem Kóta (2 body + odsazení); toleranci (H8, ±0,1) doplňte u kóty v seznamu do pole „přípona“.": "Aus der Feature-Historie abgeleitet – eine Hilfsliste, kein Ersatz für die Prüfung durch den Konstrukteur. Ein fehlendes Maß fügen Sie mit dem Werkzeug Maß hinzu (2 Punkte + Abstand); die Toleranz (H8, ±0,1) tragen Sie beim Maß in der Liste im Feld „Suffix“ ein.",
