 "Operace nevrátila objemové těleso ({0}) – jádro selhalo; změňte parametry (dráha se nesmí protínat ani být tečná k povrchu, profil musí být uzavřený a kolmý na dráhu).": "Die Operation hat keinen Volumenkörper geliefert ({0}) – der Kern ist fehlgeschlagen; ändern Sie die Parameter (der Pfad darf sich nicht selbst schneiden und nicht tangential zur Oberfläche sein, das Profil muss geschlossen und senkrecht zum Pfad sein).",
