 "Operace vrátila prázdné těleso – nejčastěji kvůli volným plochám v modelu (sešijte je nebo uzavřete do tělesa) nebo neplatné geometrii.": "Die Operation hat einen leeren Körper geliefert – meist wegen freier Flächen im Modell (nähen Sie sie oder schließen Sie sie zu einem Körper) oder ungültiger Geometrie.",
