 "osa rotace potřebuje polohu – zadejte ji hranou (osa hrana E3), válcovou plochou (osa plocha F7), dvěma body (osa body V1 V5), pomocnou osou (osa \"Osa 1\") nebo globální osou X|Y|Z": "die Rotationsachse braucht eine Lage – per Kante (achse kante E3), Zylinderfläche (achse fläche F7), zwei Punkte (achse punkte V1 V5), Hilfsachse (achse \"Achse 1\") oder globale Achse X|Y|Z",
