 "Osová / vodicí křivka musí být jiná skica než profily.": "Die Mittel-/Leitkurve muss eine andere Skizze als die Profile sein.",
 "Osová a vodicí křivka, tenká stěna": "Mittellinie und Leitkurve, dünne Wand",
