 "Ostatní (křivky)": "Sonstige (Kurven)",
 "Ostatní (volné)": "Sonstige (Freiform)",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Jen se nezobrazí 3D model.": "Die übrigen Teile des Programms funktionieren weiter: Menüs, Hilfe, Einstellungen, Öffnen und Speichern von Dateien, 2D-Skizze und Zeichnungen. Nur das 3D-Modell wird nicht angezeigt.",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Model se místo 3D okna zobrazuje jako zjednodušený náhled: pohledy, přizpůsobení, přiblížení, otáčení, řez i výběr ploch, hran a vrcholů kliknutím fungují (náhled je pravoúhlý; gizmo přesunu, skici a pomocné roviny v modelu nezobrazuje). Pro automatizaci (headless Chrome, Playwright, Puppeteer): spusťte prohlížeč bez přepínače --disable-software-rasterizer a s --enable-unsafe-swiftshader (případně --use-angle=swiftshader) – WebGL pak běží softwarově přes SwiftShader a zobrazí se plné 3D okno.": "Der Rest des Programms funktioniert weiter: Menüs, Hilfe, Einstellungen, Öffnen und Speichern von Dateien, 2D-Skizze und Zeichnungen. Statt des 3D-Fensters wird das Modell als vereinfachte Vorschau angezeigt: Ansichten, Einpassen, Zoomen, Drehen, Schnitt und Auswahl von Flächen, Kanten und Eckpunkten per Klick funktionieren (die Vorschau ist orthogonal; Verschiebe-Gizmo, Skizzen und Hilfsebenen im Modell zeigt sie nicht). Für Automatisierung (headless Chrome, Playwright, Puppeteer): Browser ohne den Schalter --disable-software-rasterizer und mit --enable-unsafe-swiftshader (bzw. --use-angle=swiftshader) starten – WebGL läuft dann per Software über SwiftShader und das volle 3D-Fenster erscheint.",
