 "Ostré rohy (jinak zaoblené)": "Scharfe Ecken (sonst gerundet)",
 "ostré rohy | zaoblené rohy": "scharfe ecken | runde ecken",
 "Ostré rohy úkosu se u tohoto profilu nepodařilo vytvořit – rohy jsou zaoblené.": "Scharfe Ecken der Schräge ließen sich für dieses Profil nicht erzeugen – die Ecken sind gerundet.",
 "Osu odkazem nelze vyřešit – jádro neposkytlo odkazy.": "Die Achsreferenz kann nicht aufgelöst werden – der Kern hat keine Referenzen bereitgestellt.",
