 "Plocha horního plechu": "Fläche des oberen Blechs",
 "Plocha je periodická přes všechny profily – bez hrany ve švu (C2). Profily se prokládají hladce: ostré rohy profilů se zaoblí, odchylku ohlásí varování.": "Die Fläche ist periodisch über alle Profile – keine Kante an der Naht (C2). Profile werden glatt angenähert: scharfe Profilecken werden verrundet, die Abweichung meldet eine Warnung.",
