 "plocha mezi dvěma hranami ploch s tečnou (G1) nebo křivostní (G2) návazností a nastavitelným napětím": "Fläche zwischen zwei Flächenkanten mit tangentialer (G1) oder krümmungsstetiger (G2) Stetigkeit und einstellbarer Spannung",
 "Plocha modelu": "Modellfläche",
