 "plocha pokračuje přes vybrané hrany o danou délku: G1 = tečně (rovně), G2 = pokračuje křivost": "die Fläche setzt sich über die gewählten Kanten um die angegebene Länge fort: G1 = tangential (gerade), G2 = Krümmung läuft weiter",
