 "plochu": "eine Fläche",
 "Plochu {0} nelze odstranit. Odstranit lze díry, čepy, kuželová zahloubení a válcová zaoblení – rovinné plochy posuňte příkazem Vytáhnout/Zatlačit.": "Fläche {0} kann nicht entfernt werden. Entfernt werden können Bohrungen, Zapfen, Kegelsenkungen und zylindrische Verrundungen – ebene Flächen verschieben Sie mit Ziehen / Drücken.",
 "Plochu {0} se nepodařilo načíst.": "Fläche {0} konnte nicht gelesen werden.",
 "plochu F{0} nelze použít: {1}": "Fläche F{0} kann nicht verwendet werden: {1}",
 "Plochu nelze zkosit kolem dělicí křivky – plocha je kolmá na směr tahu nebo ji jádro neumí naklopit.": "Die Fläche kann nicht um die Trennlinie geneigt werden – sie steht senkrecht zur Entformungsrichtung oder der Kern kann sie nicht kippen.",
 "Plochu se nepodařilo načíst.": "Die Fläche konnte nicht geladen werden.",
 "Plochu se nepodařilo odsadit – zkuste menší vzdálenost.": "Die Fläche konnte nicht versetzt werden – versuchen Sie einen kleineren Abstand.",
 "Plochu se nepodařilo zesílit – zkuste menší tloušťku nebo nejdřív plochy sešijte.": "Die Fläche konnte nicht verdickt werden – versuchen Sie eine kleinere Dicke oder nähen Sie die Flächen zuerst.",
 "Plochu tohoto typu nelze převést na B-spline (řídicí body).": "Eine Fläche dieses Typs lässt sich nicht in einen B-Spline umwandeln (Kontrollpunkte).",
 "plochu začátku": "die Startfläche",
 "plochy": "Flächen",
 "Plochy": "Flächen",
 "plochý": "flach",
 "plochy (plocha–plocha, plné zaoblení)": "Flächen (Fläche–Fläche, Vollrundung)",
 "Plochý (všechny díly)": "Flach (alle Teile)",
 "Plochy {0} se po změně modelu nenašly podle otisku – použity původní indexy.": "Flächen {0} wurden nach der Modelländerung nicht über ihre Fingerabdrücke gefunden – die ursprünglichen Indizes werden verwendet.",
 "Plochy / hrany": "Flächen / Kanten",
 "plochy <pravidlo|F1 F2…>": "flächen <regel|F1 F2…>",
 "plochý díl (rozvin) z historie ohybů – potlačením prvku se vrátí ohnutý tvar": "ebenes Teil (Abwicklung) aus der Biegehistorie – durch Unterdrücken des Features kehrt die gebogene Form zurück",
 "Plochy komponenty „{0}“ (souřadnice sestavy, {1}) – rovinné: {2}, válcové/kuželové: {3}{4}": "Flächen der Komponente „{0}“ (Baugruppenkoordinaten, {1}) – eben: {2}, zylindrisch/kegelig: {3}{4}",
 "Plochy lze místo klikání vybrat ze seznamů výše; hodnotu potvrdíte až po výběru obou ploch.": "Statt zu klicken, können die Flächen aus den Listen oben gewählt werden; den Wert bestätigen Sie erst nach der Wahl beider Flächen.",
 "Plochy lze místo klikání vybrat ze seznamů výše.": "Statt zu klicken, können die Flächen aus den Listen oben gewählt werden.",
 "Plochy lze vybrat i ze seznamu v tomto panelu; hotovou vazbu upravíte v seznamu Vazby pod stromem komponent.": "Flächen lassen sich auch aus einer Liste in diesem Panel wählen; eine fertige Verknüpfung bearbeiten Sie in der Liste Verknüpfungen unter dem Komponentenbaum.",
 "Plochy na sebe nenavazují – nejdřív je sešijte.": "Die Flächen schließen nicht aneinander an – nähen Sie sie zuerst.",
 "Plochy nejsou rovnoběžné – založena půlicí rovina.": "Die Flächen sind nicht parallel – eine Halbierungsebene wurde erstellt.",
 "Plochy netvoří jednu souvislou skořepinu – nejdřív je sešijte (Sešít plochy) nebo zvětšete toleranci.": "Die Flächen bilden keine zusammenhängende Schale – nähen Sie sie zuerst (Flächen nähen) oder erhöhen Sie die Toleranz.",
 "Plochy neuzavírají objem – {0} volných hran (chybí stěna nebo jsou mezery; zvětšete toleranci).": "Die Flächen schließen kein Volumen ein – {0} freie Kanten (eine Wand fehlt oder es gibt Lücken; erhöhen Sie die Toleranz).",
 "Plochy neuzavírají objem – chybí některá stěna nebo jsou mezery.": "Die Flächen schließen kein Volumen ein – eine Wand fehlt oder es gibt Lücken.",
 "Plochy neuzavírají objem – zkontrolujte, že na sebe navazují (Sešít plochy).": "Die Flächen schließen kein Volumen ein – prüfen Sie, ob sie aneinander anschließen (Flächen nähen).",
 "plochy odkazem (plocha–plocha, eliptické D1)": "Flächen per Referenz (Fläche–Fläche, elliptisch D1)",
 "Plochy podle pravidla „{0}“: {1}": "Flächen nach Regel „{0}“: {1}",
 "Plochy se naklopí o úhel kolem průsečnice s neutrální rovinou; směr tahu určuje, na kterou stranu se úkos otevírá (u zadané roviny jen otočí její orientaci). Bez roviny i směru platí základní rovina. Úkos na obě strany od dělicí čáry a stupňovitý úkos: přepněte Neutrální prvek na Dělicí křivka.": "Die Flächen werden um den Winkel um ihre Schnittlinie mit der neutralen Ebene gekippt; die Entformungsrichtung bestimmt, wohin sich die Schräge öffnet (bei gegebener Ebene dreht sie nur deren Orientierung). Ohne Ebene und Richtung gilt die Grundebene. Schräge zu beiden Seiten einer Trennlinie und gestufte Schräge: Neutrales Element auf Trennlinie umschalten.",
 "Plochy se rozdělí dělicí křivkou; části nad ní se zkosí ve směru tahu, části pod ní proti němu – dělicí čára zůstane na místě a díl je v ní nejširší. Skica kolmá na tah = rovinná dělicí křivka (dělicí rovina pro obě strany, přesně). Skica rovnoběžná s tahem (např. v nárysu) = profil dělicí čáry promítnutý podél normály skici: přímé úseky přesně, oblouky a spline po rovinných úsecích (přibližně), svislé skoky = stupně. Stupňovitý úkos zkosí každý úsek od vlastní roviny kolmé na tah a sousední úseky spojí stupňovými plochami.": "Die Flächen werden durch die Trennlinie geteilt; Teile oberhalb werden in Entformungsrichtung geneigt, Teile unterhalb dagegen – die Trennlinie bleibt an ihrem Platz und das Teil ist dort am breitesten. Skizze senkrecht zur Entformung = ebene Trennlinie (Trennebene für beide Seiten, exakt). Skizze parallel zur Entformung (z. B. in der Vorderansicht) = Profil der Trennlinie, entlang der Skizzennormale projiziert: gerade Abschnitte exakt, Bögen und Splines in ebenen Abschnitten (näherungsweise), senkrechte Sprünge = Stufen. Die gestufte Schräge neigt jeden Abschnitt um seine eigene Ebene senkrecht zur Entformung und verbindet benachbarte Abschnitte mit Stufenflächen.",
 "Plochy souhlasně": "Flächen gleichgerichtet",
 "Plochy styčníku jsou rovnoběžné – vyberte dvě plochy svírající úhel.": "Die Knotenblechflächen sind parallel – wählen Sie zwei Flächen, die einen Winkel bilden.",
 "Plochy tělesa": "Körperflächen",
 "Plochy třídy A": "Class-A-Flächen",
