 "Poloměr / velikost": "Radius / Größe",
 "Poloměr = polovina vzdálenosti rovnoběžných bočních ploch; prostřední plocha se nahradí válcem tečným k oběma. Prostřední plochu lze vynechat, je-li mezi bočními plochami jediná. Obdélníková prostřední plocha kolmá na boční se zaoblí přesně, jiná přibližně.": "Radius = halber Abstand der parallelen Seitenflächen; die Mittelfläche wird durch einen zu beiden tangentialen Zylinder ersetzt. Die Mittelfläche kann entfallen, wenn zwischen den Seitenflächen nur eine liegt. Eine rechteckige, zu den Seiten senkrechte Mittelfläche wird exakt verrundet, andere näherungsweise.",
 "poloměr = povrch, kde závit začíná: válec, nebo díra (jádro); hloubka jde do materiálu": "Radius = die Oberfläche, an der das Gewinde beginnt: Zylinder oder Bohrung (Kern); die Tiefe geht ins Material",
