 "poloměr podstavy (text zadává průměr D1)": "Grundradius (der Textbefehl nimmt den Durchmesser D1)",
 "Poloměr se mění lineárně od začátku hrany (R1) k jejímu konci (R2). Začátek hrany určuje model – běží-li přechod obráceně, hodnoty prohoďte. Různou vzdálenost na každé ploše (eliptický průřez) má druh „Eliptické / kuželosečkové“.": "Der Radius ändert sich linear vom Kantenanfang (R1) zum Kantenende (R2). Den Kantenanfang bestimmt das Modell – läuft der Übergang andersherum, tauschen Sie die Werte. Unterschiedliche Abstände auf jeder Fläche (elliptischer Querschnitt) bietet die Art „Elliptisch / Kegelschnitt“.",
