 "Pomocný pohled": "Hilfsansicht",
 "pomocný pohled (POHLED B, metoda šipky): kolmo na šikmou plochu viděnou jako hrana v rodičovském pohledu (skutečný tvar), podél hrany, podle rovinné plochy F… nebo směru; zarovnaně s rodičem, šipka s písmenem": "Hilfsansicht (ANSICHT B, Pfeilmethode): senkrecht auf eine schräge Fläche, die in der Elternansicht als Kante erscheint (wahre Gestalt), entlang einer Kante, nach einer ebenen Fläche F… oder einer Richtung; ausgerichtet zur Elternansicht, Pfeil mit Buchstabe",
 "pomocný pohled {0} na listu není – pomocné pohledy: {1}": "Hilfsansicht {0} ist nicht auf dem Blatt – Hilfsansichten: {1}",
