 "pomocný pohled potřebuje hranu, směr nebo plochu": "die Hilfsansicht braucht eine Kante, eine Richtung oder eine Fläche",
 "Pomocný pohled ukáže šikmou plochu ve skutečném tvaru; zalomený a natočený řez vedou čáru řezu přes několik prvků; přerušení zkrátí dlouhý díl – kóty drží skutečnou délku.": "Eine Hilfsansicht zeigt eine schräge Fläche in wahrer Gestalt; abgesetzter und gedrehter Schnitt führen die Schnittlinie durch mehrere Elemente; eine Unterbrechung verkürzt ein langes Teil – Maße behalten die wahre Länge.",
 "pomocný pohled: hrana = dva body x1 y1 x2 y2 (mm modelu v rovině rodičovského pohledu)": "Hilfsansicht: Kante = zwei Punkte x1 y1 x2 y2 (mm Modell in der Ebene der Elternansicht)",
