 "Průřez a × b": "Querschnitt a × b",
 "Průřez d2": "Querschnitt d2",
 "Průřez je oblouk elipsy (nebo kuželosečky s parametrem rho) tečný k oběma plochám: D1 se odměří na první ploše, D2 na druhé. První plocha = plocha z pole výše, jinak plocha s normálou nejvíc nahoru (+Z, pak +Y, +X). Přímá hrana mezi rovinnými plochami a kruhová hrana se stálým průřezem (rovina ⟂ osa, souosý válec/kužel) jsou přesné; jiné hrany se proloží šablonováním průřezů (přibližně, ⚠). Vnitřní hrany materiál přidají.": "Der Querschnitt ist ein Ellipsenbogen (oder Kegelschnitt mit Parameter rho), tangential zu beiden Flächen: D1 wird auf der ersten Fläche gemessen, D2 auf der zweiten. Erste Fläche = Fläche aus dem Feld oben, sonst die Fläche, deren Normale am stärksten nach oben zeigt (+Z, dann +Y, +X). Eine gerade Kante zwischen ebenen Flächen und eine Kreiskante mit konstantem Querschnitt (Ebene ⟂ Achse, koaxialer Zylinder/Kegel) sind exakt; andere Kanten werden per Loft der Querschnitte angenähert (⚠). Konkave Kanten fügen Material hinzu.",
 "Průřez svarového kovu ≈ {0} mm² (t = {1} mm) · {2} kg/m": "Schweißgutquerschnitt ≈ {0} mm² (t = {1} mm) · {2} kg/m",
