 "prvek {0}: parametr „{1}“ má hodnoty {2}": "Element {0}: Parameter „{1}“ hat die Werte {2}",
 "prvek <rozšíření>": "element <erweiterung>",
 "prvek <rozšíření> klíč=hodnota … (pole rozšíření: prvek nápověda <rozšíření>)": "element <erweiterung> schlüssel=wert … (Felder der Erweiterung: element hilfe <erweiterung>)",
 "prvek nápověda <typ> vypíše všechna pole typu pro „prvek <typ> klíč=hodnota“ (typ i slovem příkazu: díra, kužel, pružina; rozšíření id nebo popiskem). Přehled – textový příkaz · pole jen přes prvek / upravit / JSON:": "element hilfe <typ> listet alle Felder des Typs für „element <typ> schlüssel=wert“ (Typ auch per Befehlswort: bohrung, kegel, feder; Erweiterung per ID oder Bezeichnung). Übersicht – Textbefehl · Felder nur über element / bearbeiten / JSON:",
