 "prvek s chybou": "Feature mit Fehler",
 "prvek s upozorněním": "Feature mit Hinweis",
 "prvek se nepodařilo vytvořit": "das Element konnte nicht erstellt werden",
 "Prvek těleso nezměnil (objem i počet ploch zůstaly stejné) – nástroj se s tělesem nepřekrývá, leží mimo něj, nebo operace v jádře selhala. Zkontrolujte polohu a rozměry.": "Das Feature hat den Körper nicht verändert (Volumen und Flächenzahl blieben gleich) – das Werkzeug überlappt den Körper nicht, liegt außerhalb, oder die Kernoperation ist fehlgeschlagen. Prüfen Sie Position und Maße.",
