 "Roh nelze srazit – body sražení neurčují čtyřstěn.": "Die Ecke kann nicht gefast werden – die Fasenpunkte bestimmen kein Tetraeder.",
 "Roh nelze upravit (hodnota je příliš velká nebo úsečky jsou rovnoběžné).": "Die Ecke kann nicht geändert werden (der Wert ist zu groß oder die Linien sind parallel).",
 "Roh se odřízne rovinou procházející body ve vzdálenostech D1–D3 od vrcholu podél jeho tří hran (v pořadí čísel hran). Ve vrcholu se musí stýkat právě tři hrany.": "Die Ecke wird durch eine Ebene abgeschnitten, die durch Punkte in den Abständen D1–D3 vom Eckpunkt entlang seiner drei Kanten verläuft (in Reihenfolge der Kantennummern). Im Eckpunkt müssen genau drei Kanten zusammentreffen.",
