 "rohy úkosu: ostré (rovinné stěny) / zaoblené (vzdalující se rohy se zaoblí)": "Ecken der Schräge: scharf (ebene Wände) / rund (zurückweichende Ecken werden verrundet)",
 "Rohy: profily, které se ve skice stýkají koncovými body, se v rohu ořežou pokosem (obě stejně) nebo tupě (první profil průběžný, druhý zkrácený). Volné konce lze prodloužit/zkrátit.": "Ecken: Profile, deren Skizzenlinien sich in Endpunkten treffen, werden an der Ecke auf Gehrung (beide gleich) oder stumpf (erstes Profil durchlaufend, zweites gekürzt) getrimmt. Freie Enden können verlängert/gekürzt werden.",
