 "Úkos {0}° je pro tento profil příliš velký – obrys by se ve výšce {1} mm od roviny skici odsadil o {2} mm a zanikl. Zmenšete úhel nebo výšku.": "Eine Schräge von {0}° ist für dieses Profil zu groß – in einer Höhe von {1} mm über der Skizzenebene würde die Kontur um {2} mm versetzt und verschwinden. Winkel oder Höhe verkleinern.",
