 "Úkos kolem dělicí křivky nevrátil těleso.": "Die Schräge um die Trennlinie hat keinen Körper geliefert.",
 "Úkos kolem dělicí křivky se nepodařilo dopočítat (sousední plochy nelze znovu protnout) – zmenšete úhel nebo upravte výběr ploch.": "Die Schräge um die Trennlinie konnte nicht berechnet werden (Nachbarflächen lassen sich nicht neu schneiden) – verkleinern Sie den Winkel oder passen Sie die Flächenauswahl an.",
