 "Úprava (ISO 9692-1)": "Fugenvorbereitung (ISO 9692-1)",
 "Úprava {0} je pro tupý spoj dvou dílů – u vnitřního koutu použijte ½V, ½Y, K, J nebo 2J, nebo vyberte čelo dílu.": "Die Vorbereitung {0} ist für den Stumpfstoß zweier Teile – für eine innere Ecke ½V, ½Y, K, J oder 2J verwenden oder die Stirnfläche eines Teils wählen.",
 "Úprava {0} potřebuje poloměr dna R > 0.": "Die Vorbereitung {0} braucht einen Fugenradius R > 0.",
