 "Úprava dílu": "Teil wird bearbeitet",
 "úprava I, V, Y, X, U, ½V, K, J (ISO 9692-1) vyříznutá do dílů + svarový kov jako těleso; tupý, T i rohový spoj": "Fugenvorbereitung I, V, Y, X, U, ½V, K, J (ISO 9692-1) in die Teile geschnitten + Schweißgut als Körper; Stumpf-, T- und Eckstoß",
 "Úprava podsestavy": "Unterbaugruppe wird bearbeitet",
 "Úprava se vyřízne do spojovaných dílů (souměrné V, Y, X, U, 2U do obou, ½V, ½Y, K, J, 2J jen do vybraného), svarový kov s převýšením je těleso „Svar k“, podložka „Podložka k“. Náhled kreslí průřez pro zadanou tloušťku (0 = 10 mm, skutečná se změří v modelu).": "Die Vorbereitung wird in die gefügten Teile geschnitten (symmetrische V, Y, X, U, 2U in beide, ½V, ½Y, K, J, 2J nur in das gewählte); das Schweißgut mit Überhöhung ist der Körper „Svar k“, die Badsicherung „Podložka k“. Die Vorschau zeigt den Querschnitt für die angegebene Dicke (0 = 10 mm, die tatsächliche wird im Modell gemessen).",
 "úprava skici: souřadnice / rozměry / pomocná entity (cx, cy, r, průměr, a=x;y, b=…, w, h, úhel, pomocná=ano), smazání entit (i s jejich vazbami a kótami), vazeb v1… a kót k1… (čísla vypíše stav), hodnota kóty a řídicí ↔ referenční; po řádku se skica vyřeší": "Skizze bearbeiten: Koordinaten / Maße / Hilfsgeometrie eines Elements (cx, cy, r, durchmesser, a=x;y, b=…, w, h, winkel, hilfs=ja), Elemente löschen (mit ihren Bedingungen und Bemaßungen), Bedingungen v1… und Bemaßungen k1… (Nummern zeigt der Status), Bemaßungswert und steuernd ↔ Referenz; nach der Zeile wird die Skizze gelöst",
