 "Uzavřené hladce: plocha prochází profily s odchylkou až {0} mm (profily se prokládají hladce – ostré rohy se zaoblí).": "Geschlossen glatt: die Fläche läuft mit einer Abweichung bis {0} mm durch die Profile (Profile werden glatt angenähert – scharfe Ecken werden verrundet).",
