 "uzavřené volné plochy → solid (lze sloučit/odebrat s existujícím tělesem)": "geschlossene freie Flächen → Volumenkörper (lässt sich mit dem vorhandenen Körper vereinigen/abziehen)",
 "Uzavření": "Schließen",
 "uzavření lomené čáry (i se zaoblenými rohy): „uzavřít“ / „otevřená“ platí vždy, první bod = poslední → uzavřená; jinak rozhodne skica – tvoří-li čára s dalšími entitami uzavřený obrys (oba konce propojené přes jiné entity), je otevřená, jinak se uzavře a protokol to ohlásí (ne, kdyby ji uzavírací úsek křížil); vznikne-li obrys později, čára se otevře; jako dráha (tažení, žebro, dělicí čára, pole podél křivky) se automatické uzavření nepoužije": "Schließen einer Polylinie (auch mit verrundeten Ecken): „schließen“ / „offen“ gelten immer, erster Punkt = letzter → geschlossen; sonst entscheidet die Skizze – bildet die Polylinie mit anderen Elementen eine geschlossene Kontur (beide Enden über andere Elemente verbunden), ist sie offen, sonst wird sie geschlossen und das Protokoll meldet es (nicht, wenn das Schließsegment sie kreuzen würde); entsteht die Kontur später, öffnet sie sich; als Pfad (Sweep, Rippe, Trennlinie, Muster entlang einer Kurve) wird das automatische Schließen nicht verwendet",
