 "Ve Fusion: Soubor → Exportovat → typ „STEP (*.step)“.": "In Fusion: Datei → Exportieren → Typ „STEP (*.step)“.",
 "Ve schránce je jediný bod – čára potřebuje aspoň dva (čísla po dvojicích X Y).": "In der Zwischenablage ist nur ein Punkt – eine Linie braucht mindestens zwei (Zahlen in X-Y-Paaren).",
 "Ve SketchUpu: Soubor → Exportovat → 3D model → „OBJ“ nebo „STL“, ty pak otevřete zde.": "In SketchUp: Datei → Exportieren → 3D-Modell → „OBJ“ oder „STL“, diese öffnen Sie dann hier.",
 "Ve směru čela spoje do {0} mm není druhý díl – úprava se udělá jen na vybraném dílu.": "Vor der Fugenfläche liegt bis {0} mm kein anderes Teil – die Vorbereitung erfolgt nur am gewählten Teil.",
 "Ve směru normály": "In Normalenrichtung",
 "Ve směru operace není žádné těleso.": "In Richtung der Operation gibt es keinen Körper.",
 "Ve směru vysunutí není další plocha tělesa (použijte Na vzdálenost nebo Skrz vše).": "In Extrusionsrichtung gibt es keine weitere Körperfläche (verwenden Sie Blind oder Durch alles).",
 "Ve směru vysunutí za rovinou skici není těleso – nástroj míří od tělesa (zkuste Opačný směr / „obráceně“).": "In Extrusionsrichtung liegt hinter der Skizzenebene kein Körper – das Werkzeug zeigt vom Körper weg (Gegenrichtung / „umkehren“ versuchen).",
 "Ve stavovém řádku přepněte filtr výběru na Plocha a klikněte v náhledu na rovinnou plochu komponenty – rovina řezu se na ni položí. Obecnou rovinu zadáte na záložce Vektor (normála).": "Stellen Sie in der Statusleiste den Auswahlfilter auf Fläche und klicken Sie in der Vorschau auf eine ebene Fläche einer Komponente – die Schnittebene wird darauf gelegt. Eine allgemeine Ebene geben Sie im Reiter Vektor (Normale) ein.",
 "Ve středu": "Mittelpunkt",
 "Ve vrcholu [{0}] se musí stýkat právě 3 hrany (nalezeno {1}).": "Am Eckpunkt [{0}] müssen genau 3 Kanten zusammentreffen ({1} gefunden).",
 "Ve vrcholu, kde se stýkají aspoň tři vybrané hrany, zaoblení skončí ve vzdálenosti setback od vrcholu a roh uzavře hladká N-stranná záplata, tečná (G1) k zaoblením i k plochám rohu. Setback musí být alespoň rovný poloměru (stejná hodnota ≈ běžný kulový roh). Přesně pro rohy z rovinných ploch a přímých hran; jiné rohy dostanou běžné zaoblení vrcholu a prvek zobrazí ⚠.": "An einer Ecke, an der sich mindestens drei gewählte Kanten treffen, enden die Verrundungen im Rückversatz-Abstand von der Ecke und ein glatter N-seitiger Patch schließt die Ecke, tangential (G1) zu den Verrundungen und den Eckflächen. Der Rückversatz muss mindestens gleich dem Radius sein (gleicher Wert ≈ übliche Kugelecke). Exakt für Ecken aus ebenen Flächen und geraden Kanten; andere Ecken erhalten die normale Eckverrundung und das Element zeigt ⚠.",
 "Ve výrazu chybí „{0}“.": "Im Ausdruck fehlt „{0}“.",
 "Ve zdrojovém programu exportujte STEP AP214.": "Exportieren Sie im Quellprogramm STEP AP214.",
