 "ven": "nach außen",
 "Ven": "Nach außen",
 "Ven: vnější obrys se od roviny skici rozšiřuje, otvory v profilu se zužují – u odebrání se otvor do hloubky rozšiřuje (odlehčení střižnice za břitem).": "Außen: die Außenkontur erweitert sich von der Skizzenebene weg, Löcher im Profil werden enger – beim Abziehen erweitert sich die Öffnung mit der Tiefe (Freiwinkel der Schneidplatte hinter dem Steg).",
