 "výběr {0}: zadejte dva rohy x,y x,y": "Auswahl {0}: zwei Ecken x,y x,y angeben",
 "výběr entit textem stejně jako klik do modelu (i v náhledu bez WebGL): čísla jako popisky pro výběr a měřit; přidat = Ctrl + klik; nic = Esc; bez id vypíše výběr; v sestavě se stejnými komponentami #2:F3. Výběr převezmou tlačítka Zaoblit / Sražení / Skica na pásu karet a „+ aktuální výběr“ ve formulářích – textové příkazy ne: zaoblit 3 bez hran zaoblí všechny hrany, vybrané zadejte čísly (zaoblit 3 hrany E2;E5, skica plocha F3); také window.mncad.select()": "Elemente per Text auswählen wie ein Klick ins Modell (auch in der Vorschau ohne WebGL): Nummern wie bei den Auswahlbeschriftungen und messen; hinzufügen = Strg + Klick; nichts = Esc; ohne ID wird die Auswahl ausgegeben; in einer Baugruppe mit gleichen Komponenten #2:F3. Die Schaltflächen Verrunden / Fase / Skizze im Menüband und „+ aktuelle Auswahl“ in Formularen übernehmen die Auswahl – Textbefehle nicht: verrunden 3 ohne Kanten verrundet alle Kanten, die gewählten per Nummer angeben (verrunden 3 kanten E2;E5, skizze fläche F3); auch window.mncad.select()",
 "vyber F3 E2 V5 [přidat] · vyber Čep:F3 | #2:F3 | comp:Čep | \"feature:Díra 1\" | těleso · vyber nic · vyber (vypíše výběr)": "auswählen F3 E2 V5 [hinzufügen] · auswählen Bolzen:F3 | #2:F3 | comp:Bolzen | \"feature:Bohrung 1\" | körper · auswählen nichts · auswählen (gibt die Auswahl aus)",
