 "výplň potřebuje hrany otvoru: {0}": "Füllung braucht die Kanten des Lochs: {0}",
 "Výplň se nepodařilo vytvořit – hrany musí tvořit jednu uzavřenou smyčku (otvor).": "Die Füllung konnte nicht erzeugt werden – die Kanten müssen eine einzige geschlossene Schleife (Loch) bilden.",
 "Výplň: {0} z {1} hran nemá sousední plochu – u nich je jen G0.": "Füllung: {0} von {1} Kanten haben keine Nachbarfläche – dort nur G0.",
 "Výplň: dosažená tečnost {0}° (cíl < 0,1°) – zkuste méně hran nebo G0.": "Füllung: erreichte Tangentialität {0}° (Ziel < 0,1°) – weniger Kanten oder G0 versuchen.",
 "Vyplní vnitřek obrysu (otvory v obrysu se vynechají) kusy v dané rozteči; žádný kus není blíže k obrysu než okraj. Počátek rozložení = zdrojový prvek, leží-li v obrysu, jinak střed obrysu. Nejvýše 400 kusů.": "Füllt das Innere der Kontur (Löcher in der Kontur werden ausgelassen) mit Instanzen im angegebenen Abstand; keine Instanz liegt näher an der Kontur als der Rand. Ursprung der Verteilung = das Quell-Feature, wenn es in der Kontur liegt, sonst die Konturmitte. Höchstens 400 Instanzen.",
