 "výpočet {0} s": "Berechnung {0} s",
 "Výpočet byl zrušen – kliknutím se model přepočítá": "Die Berechnung wurde abgebrochen – Klick berechnet das Modell neu",
 "Výpočet modelu: {0} s": "Modellberechnung: {0} s",
 "Výpočet zrušen – model není přepočítaný. Upravte nebo potlačte náročný prvek, nebo spusťte výpočet znovu kliknutím na stav jádra.": "Berechnung abgebrochen – das Modell ist nicht neu berechnet. Bearbeiten oder unterdrücken Sie das aufwendige Element oder starten Sie die Berechnung per Klick auf den Kernstatus erneut.",
 "Výpočet zrušen – poslední změna je vrácena (Ctrl+Y ji obnoví).": "Berechnung abgebrochen – die letzte Änderung wurde zurückgenommen (Strg+Y stellt sie wieder her).",
