 "Výraz": "Ausdruck",
 "výraz „{0}“ neobsahuje proměnnou – číslo zadejte bez „=“ ({1}={0})": "der Ausdruck „{0}“ enthält keine Variable – Zahl ohne „=“ angeben ({1}={0})",
 "Výraz proměnné": "Variablenausdruck",
 "Výrobní požadavky ani poznámky se na výkres nedoplňují automaticky – uvedou se jen vyplněné.": "Fertigungsanforderungen und Anmerkungen werden nicht automatisch in die Zeichnung übernommen – nur ausgefüllte erscheinen.",
 "výrobu": "Fertigung",
 "Výřez": "Ausschnitt",
 "Výsledek je prázdný.": "Das Ergebnis ist leer.",
 "Výsledek má neplatnou geometrii (sebeprotínající nebo neorientovatelné plochy) – export STEP může selhat. Změňte parametry: profil nesmí být tečný k povrchu tělesa, dráha se nesmí protínat.": "Das Ergebnis hat eine ungültige Geometrie (selbstschneidende oder nicht orientierbare Flächen) – der STEP-Export kann fehlschlagen. Ändern Sie die Parameter: das Profil darf nicht tangential zur Körperoberfläche sein, der Pfad darf sich nicht selbst schneiden.",
 "Výsledek není těleso.": "Das Ergebnis ist kein Volumenkörper.",
 "Výsledek výrazu není konečné číslo.": "Das Ergebnis des Ausdrucks ist keine endliche Zahl.",
 "Výsledek zůstane v cílovém tělese; nástrojové těleso zanikne, pokud ho neponecháte.": "Das Ergebnis bleibt im Zielkörper; der Werkzeugkörper entfällt, wenn Sie ihn nicht behalten.",
 "Výsledné těleso není platné (sebeprotínající plochy) nebo nemá žádný solid – export STEP může selhat. Opravte prvek označený ⚠ v historii.": "Der resultierende Körper ist ungültig (selbstdurchdringende Flächen) oder hat keinen Volumenkörper – der STEP-Export kann fehlschlagen. Korrigieren Sie das mit ⚠ markierte Feature in der Historie.",
 "Vystoupit": "Erhaben",
 "Vystouplý": "Erhaben",
 "vystouplý / gravírovaný": "erhaben / graviert",
 "vystouplý lem nebo drážka podél obrysu rovinné plochy (dosedání tvárníku a tvárnice)": "erhabener Steg oder Nut entlang der Kontur einer ebenen Fläche (Tauchkante von Kern und Matrize)",
 "vystouplý nebo gravírovaný nápis na válcové ploše (radiální promítnutí)": "erhabene oder gravierte Beschriftung auf einer Zylinderfläche (radiale Projektion)",
