 "Výstřih (jazýček)": "Lasche (Ausklinkung)",
 "výstřih {0} × {1} mm, výška {2} mm, náběh {3}°": "Lasche {0} × {1} mm, Höhe {2} mm, Rampe {3}°",
 "Výstřih: délka {0} mm je pro výšku {1} mm a úhel {2}° krátká.": "Lasche: die Länge {0} mm ist für Höhe {1} mm und Winkel {2}° zu kurz.",
