 "Výstupy": "Ausgaben",
 "vysune poslední skicu; H = délka podél směru, „výška H“ = kolmo na skicu; „sklon 25 k +X“ = šikmý hranol (propad); úkos + / dovnitř = obrys se od skici zužuje, − / ven = rozšiřuje (u odebrání otvor do hloubky – odlehčení střižnice), břit N = rovná část před úkosem": "extrudiert die letzte Skizze; H = Länge entlang der Richtung, „höhe H“ = senkrecht zur Skizze; „neigung 25 nach +X“ = schräges Prisma (Durchfall); Schräge + / innen = Kontur verjüngt sich von der Skizze weg, − / außen = erweitert sich (beim Abziehen erweitert sich die Öffnung mit der Tiefe – Freiwinkel der Schneidplatte), steg N = gerader Teil vor der Schräge",
 "Vysunout": "Extrudieren",
 "vysunout H": "extrudieren H",
 "vysunout H|výška H [směr …] [sklon a [k +X]] [symetricky] [skrz|k tělesu|k dalšímu|k ploše F3|k rovině \"Rovina 1\"|k vrcholu V3] [odebrat|přidat|průnik|nové] [obráceně] [úkos a [dovnitř|ven] [břit N] [ostré rohy|zaoblené rohy]]": "extrudieren H|höhe H [richtung …] [neigung a [nach +X]] [symmetrisch] [durch|bis körper|bis nächste|bis fläche F3|bis ebene \"Ebene 1\"|bis punkt V3] [abziehen|hinzufügen|schnittmenge|neukörper] [umkehren] [schräge a [innen|außen] [steg N] [scharfe ecken|runde ecken]]",
 "vysunout H|výška H [směr x y z|směr +X|směr hrana E3|směr osa \"Osa 1\"|směr plocha F2|směr body V1 V2] [sklon a [k +X|k x y z]] [symetricky] [skrz|k tělesu|k dalšímu|k ploše F3 [odsazení N]|k rovině \"Rovina 1\"|k vrcholu V3] [odebrat|přidat|průnik|nové] [obráceně] [úkos a [dovnitř|ven] [břit N] [ostré rohy|zaoblené rohy]]": "extrudieren H|höhe H [richtung x y z|richtung +X|richtung kante E3|richtung achse \"Achse 1\"|richtung fläche F2|richtung punkte V1 V2] [neigung a [nach +X|nach x y z]] [symmetrisch] [durch|bis körper|bis nächste|bis fläche F3 [versatz N]|bis ebene \"Ebene 1\"|bis punkt V3] [abziehen|hinzufügen|schnittmenge|neukörper] [umkehren] [schräge a [innen|außen] [steg N] [scharfe ecken|runde ecken]]",
 "Vysunout opačně": "Entgegengesetzt extrudieren",
 "vysunout potřebuje výšku: {0}": "extrudieren braucht eine Höhe: {0}",
