 "Zaoblení není rovnoběžné s osami – nelze jej odstranit.": "Die Verrundung ist nicht achsparallel – sie kann nicht entfernt werden.",
 "Zaoblení plocha–plocha R{0} nelze provést – poloměr je pro společné hrany příliš velký.": "Die Fläche-Fläche-Verrundung R{0} ist nicht möglich – der Radius ist für die gemeinsamen Kanten zu groß.",
