 "zaoblení rohu se píše za bod: čára 0 0 50 0 r 5 50 30 … (r 5 zaoblí roh v bodě 50 0)": "eine Eckenverrundung steht nach dem Punkt: polylinie 0 0 50 0 r 5 50 30 … (r 5 verrundet die Ecke im Punkt 50 0)",
