 "zaoblení se nevejde na úsek mezi body {0} a {1} (délka {2}) – zmenšete poloměr": "die Verrundung passt nicht auf den Abschnitt zwischen den Punkten {0} und {1} (Länge {2}) – Radius verkleinern",
 "Zaoblení se setbackem": "Verrundung mit Rückversatz",
 "zaoblení se setbackem potřebuje poloměr: zaoblit R hrany <pravidlo> setback S": "eine Verrundung mit Rückversatz braucht einen Radius: verrunden R kanten <Regel> rückversatz S",
 "zaoblení se setbackem: zaoblení skončí S od vrcholu se 3+ hranami, roh uzavře hladká záplata G1 (výchozí S = R)": "Verrundung mit Rückversatz: die Verrundungen enden S vor einer Ecke mit 3+ Kanten, ein glatter G1-Patch schließt die Ecke (Standard S = R)",
