 "zaoblený výstupek podél úsečky ve skice (zjednodušeně, v rozvinu chybí – tvářené žebro je Žebro podél dráhy)": "gerundete Erhebung entlang einer Skizzenlinie (vereinfacht, fehlt in der Abwicklung – eine geformte Sicke ist Sicke entlang Pfad)",
 "zaoblí celou úzkou plochu (žebro, lem) do půlkruhu": "verrundet eine ganze schmale Fläche (Rippe, Steg) zum Halbkreis",
 "Zaoblí se hrany, které má plocha z první sady společné s plochou z druhé sady (např. horní plocha × všechny boční = celý obvod).": "Verrundet werden Kanten, die eine Fläche des ersten Satzes mit einer Fläche des zweiten Satzes gemeinsam hat (z. B. Oberseite × alle Seitenflächen = gesamter Umfang).",
