 "zašifrováno v úložišti do {0}, klíč je jen v odkazu": "verschlüsselt im Speicher bis {0}, der Schlüssel steht nur im Link",
 "Zatím nic. Po „Provést“ se tu objeví řádek ✓ / ✗ pro každý příkaz a textový stav dokumentu (rozměry, objem, prvky) – zpětná vazba pro agenta bez obrázku.": "Noch nichts. Nach „Ausführen“ erscheint hier für jeden Befehl eine Zeile ✓ / ✗ und der textliche Dokumentstatus (Abmessungen, Volumen, Features) – Rückmeldung für einen Agenten ohne Bild.",
 "Zatím žádné oblíbené – klikněte na hvězdičku u rodiny.": "Noch keine Favoriten – klicken Sie auf den Stern bei einer Familie.",
 "Zatím žádné soubory. Vše, co uložíte nebo otevřete, se objeví tady (šifrovaně, jen pro vás).": "Noch keine Dateien. Alles, was Sie speichern oder öffnen, erscheint hier (verschlüsselt, nur für Sie).",
 "Zatím žádný motor. Rotační motor otáčí komponentou na vazbě Závěs / Souosost / Šroub, lineární ji posouvá na vazbě Vzdálenost / Drážka / Dráha / Souosost.": "Noch kein Antrieb. Ein Drehantrieb dreht eine Komponente an Scharnier / Konzentrisch / Schraube, ein Linearantrieb verschiebt sie an Abstand / Langloch / Pfad / Konzentrisch.",
