 "Závit (ISO metrický – hrubé i jemné stoupání)": "Gewinde (ISO-metrisch – Regel- und Feingewinde)",
 "závit (M8, M18×1,5)": "Gewinde (M8, M18×1,5)",
 "Závit 60°": "Gewinde 60°",
 "závit čela": "Stirngewinde",
 "závit M18×1,5 délka L [v x y z | na …] [osa …] [vnitřní] [modelovat]": "gewinde M18×1,5 länge L [bei x y z | bei …] [achse …] [innen] [modellieren]",
 "závit M18×1,5 délka L [vnitřní] [modelovat]": "gewinde M18×1,5 länge L [innen] [modellieren]",
 "závit M8": "gewinde M8",
 "závit na válci (vnější) nebo v díře (vnitřní); kosmetický = jen ve výkrese, „modelovat“ = drážky v geometrii": "Gewinde auf einem Zylinder (außen) oder in einer Bohrung (innen); kosmetisch = nur in der Zeichnung, „modellieren“ = Gewindegänge in der Geometrie",
 "závit nemá operaci – kosmetický je jen ve výkrese, „modelovat“ vyřízne drážky: {0}": "ein Gewinde hat keine Operation – kosmetisch nur in der Zeichnung, „modellieren“ schneidet die Rillen: {0}",
 "Závit podle průměru díry (ISO 273), délka podle sevřené tloušťky; hlava na straně kliknutí. Přidá se vazba Souosost.": "Gewinde nach Bohrungsdurchmesser (ISO 273), Länge nach Klemmlänge; Kopf auf der angeklickten Seite. Eine Verknüpfung Koaxial wird hinzugefügt.",
 "závit potřebuje délku: závit M18×1,5 délka 20": "Gewinde braucht eine Länge: gewinde M18×1,5 länge 20",
 "závit potřebuje označení M2 až M48 (hrubé nebo jemné stoupání, např. M18×1,5): závit M18×1,5 délka 20 v 0 0 10 [osa Z] [vnitřní] [modelovat]{0}": "Gewinde braucht eine Bezeichnung M2 bis M48 (Regel- oder Feingewinde, z. B. M18×1,5): gewinde M18×1,5 länge 20 bei 0 0 10 [achse Z] [innen] [modellieren]{0}",
 "Závit potřebuje těleso (válcovou plochu nebo díru).": "Ein Gewinde braucht einen Körper (eine Zylinderfläche oder eine Bohrung).",
 "Závit potřebuje těleso (válcovou plochu).": "Ein Gewinde braucht einen Körper (eine Zylinderfläche).",
 "Závit se vymodeluje jako drážky (zjednodušeně, bez stoupání) – vhodné pro vizualizaci a 3D tisk. Skutečnou šroubovici dává Plochy → Tažení po šroubovici (profil Závit 60°).": "Das Gewinde wird als Rillen modelliert (vereinfacht, ohne Steigung) – geeignet für Visualisierung und 3D-Druck. Eine echte Schraubenlinie liefert Flächen → Austragung entlang Schraubenlinie (Profil Gewinde 60°).",
 "Závit zadní": "Gewinde hinten",
 "Závitová díra": "Gewindebohrung",
 "Závitová díra 1": "Gewindebohrung 1",
 "Závitová díra 2": "Gewindebohrung 2",
 "závitová díra: bez průměru = tabulkový vrták (M8 → 6,8, M18×1,5 → 16,5); zadaný průměr má přednost (protokol: vrták zadán ručně); jmenovitý průměr (díra 8 závit M8) = tabulkový vrták s poznámkou; „jádro“ (EN core, DE Kern) = malý průměr D1 podle ISO 965-1 (M8 → 6,647); „vrták N“ (EN drill N, DE Bohrer N) = vlastní vrták. Dno slepé díry: „dno ploché“ (EN flat bottom, DE flacher Grund) – sedlo pružiny, frézované dno – nebo „hrot 118|120|90“ (EN tip, DE Spitze; 60–170°, „hrot 180“ = ploché; také „ploché“, „bez hrotu“, „dno kužel 120“); platí i pro závitovou a zahloubenou díru; volby díry pište před „název“": "Gewindebohrung: ohne Durchmesser = Tabellen-Kernlochbohrer (M8 → 6,8, M18×1,5 → 16,5); ein angegebener Durchmesser hat Vorrang (Protokoll: Bohrer manuell angegeben); der Nenndurchmesser (bohrung 8 gewinde M8) = Tabellen-Kernlochbohrer mit Hinweis; „Kern“ (CZ jádro, EN core) = Kerndurchmesser D1 nach ISO 965-1 (M8 → 6,647); „Bohrer N“ (CZ vrták N, EN drill N) = eigener Bohrer. Sacklochgrund: „flacher Grund“ (CZ dno ploché, EN flat bottom) – Federsitz, gefräster Grund – oder „Spitze 118|120|90“ (CZ hrot, EN tip; 60–170°, „Spitze 180“ = flach; auch „flach“, „ohne Spitze“, „Grund Kegel 120“); gilt auch für Gewinde- und Senkbohrungen; die Bohrungsoptionen vor „name“ schreiben",
