 "změní parametry existujícího prvku na místě (prvek = název v uvozovkách, id, $last nebo @3 = 3. prvek historie); klíče jako u příkazu prvek, u rozšíření i popisek; plochy / hrany čísly, E7 / F3 nebo pravidlem nad tělesem před prvkem; „==výraz“ naváže parametr na proměnné, číslo vazbu zruší; bez klíčů vypíše parametry": "ändert die Parameter eines vorhandenen Features direkt (Feature = Name in Anführungszeichen, ID, $last oder @3 = 3. Feature im Verlauf); Schlüssel wie beim Befehl element, bei Erweiterungen auch die Beschriftung; Flächen / Kanten per Nummer, E7 / F3 oder per Regel am Körper vor dem Feature; „==Ausdruck“ bindet den Parameter an Variablen, eine Zahl hebt die Bindung auf; ohne Schlüssel listet es die Parameter",
 "změní pořadí v historii; skica (použitý prvek) musí zůstat před prvky, které ji používají – jinak ✗ s důvodem": "ändert die Reihenfolge im Verlauf; eine Skizze (verwendetes Feature) muss vor den Features bleiben, die sie verwenden – sonst ✗ mit Grund",
