 "Způsoby zadání: vrchol, střed / začátek / konec hrany, střed kružnice, střed plochy, bod v % délky hrany, střed mezi body, mezi body v poměru, odsazený podél hrany, průmět na plochu, průsečík hrany s plochou, počátek, souřadnice, bod skici. Bod pak slouží jako poloha díry, primitiva, střed otáčení…": "Eingabearten: Eckpunkt, Kantenmitte / -anfang / -ende, Kreismittelpunkt, Flächenmittelpunkt, Punkt bei % der Kantenlänge, Mitte zwischen Punkten, zwischen Punkten im Verhältnis, versetzt entlang einer Kante, Projektion auf eine Fläche, Schnittpunkt Kante–Fläche, Ursprung, Koordinaten, Skizzenpunkt. Der Punkt dient dann als Bohrungsposition, Grundkörperposition, Drehmitte…",
