 "Zrcadlený prvek „{0}“ nemá nástrojové těleso – zrcadlit lze vysunutí, rotace, primitiva, díry, tažení a text.": "Das gespiegelte Element „{0}“ hat keinen Werkzeugkörper – spiegeln lassen sich Extrusionen, Rotationen, Grundkörper, Bohrungen, Austragungen und Text.",
